const entryAnalytics=renderAnalytics;renderAnalytics=function(){entryAnalytics();const groups=EntryCore.groups(analyticsRows(),data);const panel=document.createElement('article');panel.className='panel';panel.id='entry-analysis';panel.innerHTML='<h2>Win Rate ตามเงื่อนไขเข้า Position</h2><p>เฉพาะ Futures ที่มีผลปิด ตามช่วงเวลา พอร์ต Layer สกุลเงิน และวิธีนับด้านบน · รวมเสมอในฐาน Win Rate · ไม่นับ Funding แยกเป็นครั้งชนะ/แพ้ · ข้อมูลเก่าที่ยังไม่กรอกแสดงเป็น “ยังไม่ระบุ” จำนวนตัวอย่างน้อยอาจทำให้ผลเปลี่ยนมาก</p>'+groups.map(g=>'<h3>'+g.title+'</h3>'+analyticsTable(g.groups)).join('');$('#feature-page .panel').after(panel)};
const entryReview=reviewText;reviewText=function(rows,start,end){return entryReview(rows,start,end)+'\n\nWin Rate ตามเงื่อนไขเข้า Position\n'+EntryCore.groups(rows,data).map(g=>g.title+'\n'+g.groups.map(r=>r.name+': '+r.count+' รายการ, Win Rate '+metric(r.winRate,'USD')+'%, กำไรสุทธิ '+metric(r.net)+' '+currency).join('\n')).join('\n\n')};
render();
